"""Render the markdown index and the README counts block from a catalog."""
from __future__ import annotations

from collections import Counter

START = "<!-- counts:start (generated by `rig-directory readme`; do not edit by hand) -->"
END = "<!-- counts:end -->"


def _cell(text: str, limit: int = 140) -> str:
    text = " ".join(str(text).split()).replace("|", "\\|")
    return text if len(text) <= limit else text[: limit - 1].rstrip() + "…"


def render_index(c: dict) -> str:
    n = c["counts"]
    out = [
        "# RIG Agent Directory: generated index",
        "",
        "Generated by `rig-directory index` from `catalog/catalog.json`. Do not edit by hand.",
        "",
        f"{n['repos']} public repos ({n['repos_crawled']} crawled), {n['skills']} skills, "
        f"{n['agents']} agents, {n['engines']} deviation engines.",
        "",
        "## Repos",
        "",
        "| Repo | Skills | Agents | Engines | Test files | Description |",
        "|---|---|---|---|---|---|",
    ]
    for r in c["repos"]:
        flag = " (fork, not crawled)" if r["fork"] else ""
        k = r["counts"]
        out.append(
            f"| [{r['name']}]({r['url']}){flag} | {k['skills']} | {k['agents']} | {k['engines']} | "
            f"{r['test_files']} | {_cell(r['description'])} |"
        )
    out += ["", "## Skills", "", "| Skill | Pack | Repo | Description |", "|---|---|---|---|"]
    for s in c["skills"]:
        out.append(f"| [{_cell(s['name'])}]({s['url']}) | {s['pack'] or ''} | {s['repo']} | {_cell(s['description'])} |")
    out += ["", "## Agents", ""]
    by_dept: dict[str, list[dict]] = {}
    for a in c["agents"]:
        by_dept.setdefault(a["department"] or "(none)", []).append(a)
    for dept, items in by_dept.items():
        out += [f"### {dept} ({len(items)})", "", "| Agent | Repo | Description |", "|---|---|---|"]
        for a in items:
            out.append(f"| [{_cell(a['name'])}]({a['url']}) | {a['repo']} | {_cell(a['description'])} |")
        out.append("")
    out += ["## Deviation engines", "", "| # | Codename | Layer | Full name | Description |", "|---|---|---|---|---|"]
    for e in c["engines"]:
        out.append(f"| {e['id']} | [{e['codename']}]({e['url']}) | {e['layer']} | {_cell(e['full_name'])} | {_cell(e['description'])} |")
    return "\n".join(out) + "\n"


def render_counts_block(c: dict) -> str:
    n = c["counts"]
    lines = [
        START,
        f"Counted from `catalog/catalog.json` ({n['repos']} public repos listed, {n['repos_crawled']} crawled):",
        "",
        "| Kind | Count |",
        "|---|---|",
        f"| Public repos | {n['repos']} |",
        f"| Skills | {n['skills']} ({n['skills_unique_names']} unique names) |",
        f"| Agents | {n['agents']} ({n['agents_unique_names']} unique names) |",
        f"| Deviation engines | {n['engines']} |",
        "",
    ]
    depts = Counter(a["department"] or "(none)" for a in c["agents"])
    layers = Counter(e["layer"] for e in c["engines"])
    if depts:
        lines.append("Agents by department: " + ", ".join(f"{d} {k}" for d, k in sorted(depts.items())) + ".")
        lines.append("")
    if layers:
        lines.append("Engines by layer: " + ", ".join(f"{d} {k}" for d, k in sorted(layers.items())) + ".")
        lines.append("")
    lines.append(END)
    return "\n".join(lines)


def update_readme(readme: str, c: dict) -> str:
    block = render_counts_block(c)
    if START in readme and END in readme:
        head, rest = readme.split(START, 1)
        _, tail = rest.split(END, 1)
        return head + block + tail
    raise ValueError("README has no counts markers")
